(function () {
  /* Hero animation: assets/hero.mp4 is scrubbed by scroll position.
     The video is encoded with a keyframe on every frame so seeking is smooth. */
  const video = document.getElementById('hero-video');

  // The video is embedded below as base64, so no separate video file is needed.
  const HERO_VIDEO_BASE64 = "";
  (function () {
    const bin = atob(HERO_VIDEO_BASE64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    video.innerHTML = '';
    video.src = URL.createObjectURL(new Blob([bytes], { type: 'video/mp4' }));
  })();
  const loader = document.getElementById('loader');
  const loaderBar = document.getElementById('loader-bar');
  const wrapper = document.querySelector('.sequence-wrapper');

  let targetTime = 0;
  let ticking = false;

  function updateTarget() {
    const rect = wrapper.getBoundingClientRect();
    const scrollable = wrapper.offsetHeight - window.innerHeight;
    const progress = Math.max(0, Math.min(1, -rect.top / scrollable));
    if (video.duration) targetTime = progress * (video.duration - 0.001);
  }

  function seekLoop() {
    // Only issue a new seek once the previous one finished (avoids stalls).
    if (!video.seeking && Math.abs(video.currentTime - targetTime) > 0.001) {
      video.currentTime = targetTime;
    }
    if (ticking) requestAnimationFrame(seekLoop);
  }

  function onScroll() {
    updateTarget();
    if (!ticking) { ticking = true; requestAnimationFrame(seekLoop); }
  }

  function ready() {
    loader.classList.add('hidden');
    updateTarget();
    video.currentTime = targetTime;
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
  }

  video.pause();
  video.addEventListener('progress', () => {
    if (video.buffered.length && video.duration) {
      const pct = Math.round((video.buffered.end(video.buffered.length - 1) / video.duration) * 100);
      loaderBar.style.setProperty('--progress', pct + '%');
    }
  });
  video.addEventListener('canplaythrough', ready, { once: true });
  video.addEventListener('error', () => loader.classList.add('hidden'), true);
  // Safety net: never leave the loader up forever on slow connections.
  setTimeout(() => loader.classList.add('hidden'), 8000);
  if (video.readyState >= 4) ready();
})();

