  /* --------------------------------------------------------------
     HERO VISIBILITY — the frame sequence must only ever be visible
     while its section is on screen. As soon as the user scrolls (or
     nav-jumps) past it into About / Projects / Tech Stack / Reviews /
     Contact, force it hidden — a safety net on top of the sticky
     behaviour so the animation can never bleed into other tabs.
  -------------------------------------------------------------- */
  const heroSticky = document.querySelector('.sequence-sticky');
  const heroWrapper = document.querySelector('.sequence-wrapper');
  if (heroSticky && heroWrapper && 'IntersectionObserver' in window) {
    const heroObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        heroSticky.classList.toggle('hero-hidden', !entry.isIntersecting);
      });
    }, { threshold: 0 });
    heroObserver.observe(heroWrapper);
  }

  /* --------------------------------------------------------------
     NAV — scroll state, mobile panel, smooth scroll
  -------------------------------------------------------------- */
  const navbar = document.getElementById('navbar');
  window.addEventListener('scroll', () => {
    navbar.classList.toggle('is-scrolled', window.scrollY > 40);
  }, { passive: true });

  const navToggle = document.getElementById('navToggle');
  const navMobilePanel = document.getElementById('navMobilePanel');
  navToggle.addEventListener('click', () => {
    const isOpen = navMobilePanel.classList.toggle('is-open');
    navToggle.setAttribute('aria-expanded', String(isOpen));
  });
  navMobilePanel.querySelectorAll('a').forEach(a => {
    a.addEventListener('click', () => {
      navMobilePanel.classList.remove('is-open');
      navToggle.setAttribute('aria-expanded', 'false');
    });
  });

  /* Only the Home link (#top) is allowed to smooth-scroll, because that
     scroll is what plays the canvas frame sequence. Every other nav
     destination jumps instantly so the hero animation never plays as a
     side effect of navigating to About / Projects / Tech Stack /
     Reviews / Contact. */
  document.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', (e) => {
      const id = a.getAttribute('href').slice(1);
      const target = document.getElementById(id);
      if (!target) return;
      e.preventDefault();
      const isHome = id === 'top';
      target.scrollIntoView({ behavior: isHome ? 'smooth' : 'auto', block: 'start' });
    });
  });

  const yearEl = document.getElementById('year');
  if (yearEl) yearEl.textContent = new Date().getFullYear();

