/* ====================================================================
   ENHANCEMENTS — custom magnetic cursor, scroll-reveal animations,
   tilt-on-hover project cards, animated stat counters.
   Respects prefers-reduced-motion throughout.
   ==================================================================== */
(function () {
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const isTouch = window.matchMedia('(hover: none), (pointer: coarse)').matches;

  /* ------------------------------------------------------------
     CUSTOM MAGNETIC CURSOR
  ------------------------------------------------------------ */
  if (!reduceMotion && !isTouch) {
    const dot = document.createElement('div');
    dot.className = 'cursor-dot';
    const ring = document.createElement('div');
    ring.className = 'cursor-ring';
    document.body.append(dot, ring);
    document.body.classList.add('cursor-ready');

    let mouseX = 0, mouseY = 0;
    let ringX = 0, ringY = 0;

    window.addEventListener('mousemove', (e) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
      dot.style.transform = `translate(${mouseX}px, ${mouseY}px) translate(-50%, -50%)`;
    });

    function animateRing() {
      ringX += (mouseX - ringX) * 0.18;
      ringY += (mouseY - ringY) * 0.18;
      ring.style.transform = `translate(${ringX}px, ${ringY}px) translate(-50%, -50%)`;
      requestAnimationFrame(animateRing);
    }
    animateRing();

    const magneticTargets = 'a, button, .project-card, .tech-badge, .social-link';
    document.addEventListener('mouseover', (e) => {
      if (e.target.closest(magneticTargets)) ring.classList.add('is-active');
    });
    document.addEventListener('mouseout', (e) => {
      if (e.target.closest(magneticTargets)) ring.classList.remove('is-active');
    });
  }

  /* ------------------------------------------------------------
     SCROLL-TRIGGERED REVEAL ANIMATIONS
     Applied to section headers, about content, and every card in
     the projects / tech / reviews grids, with a small stagger.
  ------------------------------------------------------------ */
  function markReveal(list) {
    list.forEach((el, i) => {
      el.classList.add('reveal');
      el.style.setProperty('--reveal-index', i % 6);
    });
  }

  // Give the dynamically-rendered grids a beat to finish injecting HTML.
  requestAnimationFrame(() => {
    markReveal(document.querySelectorAll('.section-head .eyebrow, .section-head .section-title, .section-head .section-sub'));
    markReveal(document.querySelectorAll('.about-body > *'));
    markReveal(document.querySelectorAll('.stat-card'));
    markReveal(document.querySelectorAll('.projects-grid .project-card'));
    markReveal(document.querySelectorAll('.tech-grid .tech-badge'));
    markReveal(document.querySelectorAll('.reviews-grid .review-card'));
    markReveal(document.querySelectorAll('.contact-card > *'));

    if (reduceMotion || !('IntersectionObserver' in window)) {
      document.querySelectorAll('.reveal').forEach(el => el.classList.add('is-visible'));
      return;
    }

    const revealObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          revealObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));
  });

  /* ------------------------------------------------------------
     TILT-ON-HOVER PROJECT CARDS
     Rotation follows the pointer position within the card.
  ------------------------------------------------------------ */
  if (!reduceMotion && !isTouch) {
    requestAnimationFrame(() => {
      document.querySelectorAll('.project-card').forEach((card) => {
        const inner = card.querySelector('.project-card-inner');
        if (!inner) return;

        card.addEventListener('mousemove', (e) => {
          const rect = card.getBoundingClientRect();
          const x = (e.clientX - rect.left) / rect.width - 0.5;
          const y = (e.clientY - rect.top) / rect.height - 0.5;
          const rotateX = (-y * 10).toFixed(2);
          const rotateY = (x * 12).toFixed(2);
          inner.style.transform = `rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-6px)`;
        });

        card.addEventListener('mouseleave', () => {
          inner.style.transform = 'rotateX(0deg) rotateY(0deg) translateY(0)';
        });
      });
    });
  }

  /* ------------------------------------------------------------
     ANIMATED STAT COUNTERS
     Parses each .stat-num for a leading number and a trailing
     suffix (+, %, or nothing), then counts up once visible.
  ------------------------------------------------------------ */
  function animateCount(el) {
    const raw = el.textContent.trim();
    const match = raw.match(/^(\d+)(.*)$/);
    if (!match) return;
    const target = parseInt(match[1], 10);
    const suffix = match[2];

    if (reduceMotion) {
      el.textContent = target + suffix;
      return;
    }

    const duration = 1200;
    const start = performance.now();

    function tick(now) {
      const progress = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = Math.round(eased * target) + suffix;
      if (progress < 1) {
        requestAnimationFrame(tick);
      } else {
        el.textContent = target + suffix;
        el.classList.add('is-counting');
      }
    }
    requestAnimationFrame(tick);
  }

  requestAnimationFrame(() => {
    const statNums = document.querySelectorAll('.stat-num');
    if (!statNums.length) return;

    if (!('IntersectionObserver' in window)) {
      statNums.forEach(animateCount);
      return;
    }

    const statObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          animateCount(entry.target);
          statObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.5 });

    statNums.forEach(el => statObserver.observe(el));
  });
})();
